import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';

// ========================================
// LAYOUTS
// ========================================
// import { InsuranceLayout } from './components/layout/insurance';
import { CustomerLayout } from './components/layout/customer'; // TODO: สร้าง CustomerLayout
// import { GarageLayout } from './components/layout/garage'; // TODO: สร้าง GarageLayout

// ========================================
// INSURANCE PAGES
// ========================================
import {
  ActiveClaims,     // หน้าแสดงเคสที่กำลังดำเนินการ
  CreateClaim,      // หน้าเปิดเคสเคลมใหม่
  ClaimDetail,      // หน้ารายละเอียดเคส + อัปโหลดรายงาน
  ClaimHistory,     // หน้าประวัติเคสที่เสร็จสิ้นแล้ว
  Approvals,        // หน้าจัดการคำขออนุมัติ (ลูกค้า + อู่)
  Analytics         // หน้าวิเคราะห์ข้อมูล + รายงาน
} from './pages/insurance';

// ========================================
// CUSTOMER PAGES (เปิดใช้งานแล้ว)
// ========================================
import {
  CustomerDashboard,        // หน้าแดชบอร์ดลูกค้า - ดูสถานะเคลม
  CustomerClaimDetail,      // หน้ารายละเอียดเคลม + ดาวน์โหลด PDF
  GarageSelection,          // หน้าเลือกอู่ซ่อม
  UrgentRepairRequest,      // หน้าขออนุมัติซ่อมด่วน
  ComplaintForm,            // หน้าแจ้งร้องเรียน
  SatisfactionSurvey,       // หน้าประเมินความพึงพอใจ (หลังเคลมเสร็จ)
} from './pages/customer';

// ========================================
// GARAGE PAGES (TODO)
// ========================================
// import {
//   GarageDashboard,          // หน้าแดชบอร์ดอู่ - ดูรายการซ่อมทั้งหมด
//   GarageClaimDetail,        // หน้ารายละเอียดการซ่อม + อัพเดตสถานะ
//   AdditionalCostRequest,    // หน้าขออนุมัติรายการเพิ่มเติม
//   RepairProgress,           // หน้าอัพเดตความคืบหน้าการซ่อม
// } from './pages/garage';

/**
 * App Component - Main Router
 * 
 * Routes Structure:
 * - / - Redirect to /customer (default)
 * - /insurance/* - Insurance Company Portal
 * - /customer/* - Customer Portal ✅ (เปิดใช้งานแล้ว)
 * - /garage/* - Garage Portal (TODO)
 */
function App() {
  return (
    <Router>
      <Routes>
        {/* ========================================
            ROOT - Redirect to Customer
            ======================================== */}
        <Route path="/" element={<Navigate to="/customer" replace />} />

        {/* ========================================
            CUSTOMER PORTAL ✅ (เปิดใช้งานแล้ว)
            ======================================== */}
        <Route path="/customer" element={<CustomerLayout />}>
          {/* Dashboard - ดูสถานะเคลมทั้งหมด */}
          <Route index element={<Dashboard />} />
          
          {/* Claim Detail - ดูรายละเอียดเคลม */}
          {/* - ดูสถานะ timeline */}
          {/* - ดาวน์โหลดใบเคลม PDF */}
          {/* - ดูค่าเสียหายที่ต้องจ่ายเพิ่ม (ถ้ามี) */}
          <Route path="claims/:id" element={<ClaimDetail />} />
          
          {/* Garage Selection - เลือกอู่ซ่อม */}
          {/* - ดูรายชื่ออู่ */}
          {/* - ดูระยะทางจากตัวลูกค้า */}
          {/* - ดูรายละเอียดอู่ */}
          <Route path="garages" element={<Selec />} />
          
          {/* Urgent Repair Request - ขออนุมัติซ่อมด่วน */}
          {/* - กรอกเหตุผล */}
          {/* - อัปโหลดเอกสารประกอบ */}
          <Route path="claims/:id/urgent-repair" element={<UrgentRepairRequest />} />
          
          {/* Complaint Form - แจ้งร้องเรียน */}
          <Route path="complaints" element={<ComplaintForm />} />
          
          {/* Satisfaction Survey - ประเมินความพึงพอใจ */}
          {/* (แสดงเฉพาะเมื่อเคลมเสร็จสิ้น) */}
          <Route path="claims/:id/survey" element={<SatisfactionSurvey />} />
        </Route>

        {/* ========================================
            GARAGE PORTAL (TODO)
            ======================================== */}
        {/* <Route path="/garage" element={<GarageLayout />}> */}
          {/* Dashboard - ดูรายการซ่อมทั้งหมด */}
          {/* <Route index element={<GarageDashboard />} /> */}
          
          {/* Claim Detail - รายละเอียดการซ่อม */}
          {/* - รับรายการซ่อม (ใบเคลม) */}
          {/* - อัพเดตสถานะการซ่อม */}
          {/* <Route path="claims/:id" element={<GarageClaimDetail />} /> */}
          
          {/* Additional Cost Request - ขออนุมัติรายการเพิ่มเติม */}
          {/* (ถ้าวงเงินไม่เพียงพอ) */}
          {/* <Route path="claims/:id/additional-cost" element={<AdditionalCostRequest />} /> */}
          
          {/* Repair Progress - อัพเดตความคืบหน้า */}
          {/* - ตรวจสอบใบเคลม */}
          {/* - ยืนยันรับซ่อม */}
          {/* - จัดเตรียมอะไหล่ */}
          {/* - ซ่อมแซม */}
          {/* <Route path="claims/:id/progress" element={<RepairProgress />} /> */}
        {/* </Route> */}

        {/* ========================================
            404 NOT FOUND
            ======================================== */}
        <Route path="*" element={
          <div className="flex items-center justify-center min-h-screen bg-neutral-50">
            <div className="text-center">
              <h1 className="text-6xl font-bold text-neutral-300 mb-4">404</h1>
              <p className="text-xl text-neutral-500 mb-6">ไม่พบหน้าที่คุณต้องการ</p>
              <a href="/" className="btn-primary">
                กลับหน้าหลัก
              </a>
            </div>
          </div>
        } />
      </Routes>
    </Router>
  );
}

export default App;
